// Snake trail
// For the #WCCChallenge << What's left behind >> (join the discord! https://discord.gg/S8c7qcjw2b)

/*
 * Just a snake pooping colors // End of comment
 * Press "space" to pause and admire the mess
 */


let snake
let gridSize = 40
let cols, rows
let cw = 800, ch = 800
let food
let foodNum = 10
let cnv
let WALL_COLOR = 0
let BG_COLOR
let SNAKE_COLOR
let paused = false
let showScores = true
let currentScore, maxScore

let fPalettes = [
  ["#fafafa", "#4464a1", "#62b6de", "#b3dce0", "#ffc5c7", "#ee726b", "#cd1440"],
  ["#fffbe6", "#abcd5e", "#29ac9f", "#14976b", "#b3dce0", "#62b6de", "#2b67af", "#f589a3", "#ef562f", "#fc8405", "#f9d531"],
  ["#81BB9B", "#14A1A6", "#044e9e", "#6190d3", "#fcf7ed", "#fcd494", "#f4b804"],
  ["#A66714", "#F2961D", "#05668D", "#028090", "#00A896", "#02C39A", "#F0F3BD"],
]
let palette

function setup() {
  let tmpPalette = [...random(fPalettes)]
  BG_COLOR = tmpPalette.shift()
  SNAKE_COLOR = tmpPalette.shift()
  palette = tmpPalette

  food = []
  createCanvas(cw + 2 * gridSize, ch + 2 * gridSize)
  cols = floor(cw / gridSize)
  rows = floor(ch / gridSize)
  frameRate(10)
  snake = new Snake(...getCenter())
  spawnFood()
  cnv = createGraphics(cw, ch)
  cnv.pixelDensity(2)
  cnv.strokeCap(SQUARE)
  pixelDensity(2)
  strokeCap(SQUARE)
  texture = granulate(200)
	currentScore = snake.body.length
	maxScore = max(currentScore, maxScore)
	textAlign(LEFT, CENTER)
}

function draw() {
  background(BG_COLOR)
	fill(WALL_COLOR)
	rect(0, 0, width, height)
  noStroke()
  fill(BG_COLOR)
  rect(gridSize, gridSize, cw, ch)

	if (!paused && showScores) {	
		fill('white')
		textSize(gridSize * 0.5)
		text(`Current: ${currentScore} | Max: ${maxScore}`, gridSize, gridSize/2)
	}

  push()
  translate(gridSize, gridSize)

  for (let f of food) {
    if (snake.eat(f)) {
      spawnFood()
    }
  }

  if (!paused) {
    snake.update()
  }

	currentScore = snake.body.length
	maxScore = max(currentScore, maxScore)

  image(cnv, 0, 0)
  if (!paused) {
    snake.draw()
  }
  fill(255, 0, 0)
  if (!paused) {
    for (let f of food) {
      f.draw()
    }
  }
  if (snake.crashed()) {
    snake.die()
    snake.respawn(...getCenter())
  }
  tint(255, 255, 255, 75)
  image(texture, 0, 0)
  tint(255, 255, 255, 255)
  pop()
}

function spawnFood() {
  let _wG_1 = 0; while ((food.length < foodNum) && ++_wG_1 < 20000) {
    let x = floor(random(cols)) * gridSize
    let y = floor(random(rows)) * gridSize
    while (food.find((f) => f.x === x && f.y === y)) {
      x = floor(random(cols)) * gridSize
      y = floor(random(rows)) * gridSize
    }
    let foodType
    if (random() < 0.7) {
      foodType = random([
        BicolorHFood,
        BicolorVFood,
        TriangleFood,
        TriangleFood2,
        SquareFood,
      ])
    } else {
      foodType = random([HLine, VLine, DRLine, DLLine])
    }
    let _food = new foodType(x, y)
    food.push(_food)
  }
}

let getCenter = () => {
  return [
    floor(width / 2 / gridSize) * gridSize,
    floor(height / 2 / gridSize) * gridSize,
  ]
}

function keyPressed() {
  if (keyCode === UP_ARROW && snake.ySpeed !== 1) {
    snake.setDirection(0, -1)
  } else if (keyCode === DOWN_ARROW && snake.ySpeed !== -1) {
    snake.setDirection(0, 1)
  } else if (keyCode === LEFT_ARROW && snake.xSpeed !== 1) {
    snake.setDirection(-1, 0)
  } else if (keyCode === RIGHT_ARROW && snake.xSpeed !== -1) {
    snake.setDirection(1, 0)
  } else if (keyCode === 32) {
    // Space
    paused = !paused
  } else if (keyCode === 83) { // "S"
		showScores = !showScores
	} else if (keyCode === 67) { // "C"
		cnv.clear()
	}
}

class Food {
  constructor(x, y) {
    this.color1 = random(palette)
    this.color2 = random(palette)

    let _wG_2 = 0; while ((this.color1 === this.color2) && ++_wG_2 < 20000) {
      this.color2 = random(palette)
    }
    this.x = x
    this.y = y
    this.r = gridSize * 1.2
    this.isPower = true
  }

  draw() {
    strokeWeight(5)
    stroke(0)
    noFill()
    circle(this.x + gridSize / 2, this.y + gridSize / 2, this.r)
  }
}

class SubFood extends Food {
  constructor(x, y) {
    super(x, y)
    this.isPower = false
    this.r = gridSize * 0.8
  }

  draw() {
    strokeWeight(3)
    stroke(this.color1)
    fill(BG_COLOR)
    circle(this.x + gridSize / 2, this.y + gridSize / 2, this.r)
  }
}

class VLine extends SubFood {
  draw() {
    super.draw()
    stroke(this.color1)
    strokeWeight(3)
    line(
      this.x + gridSize / 2,
      this.y + (gridSize - this.r) / 2,
      this.x + gridSize / 2,
      this.y + gridSize - (gridSize - this.r) / 2
    )
  }
  trail(pos, direction) {
    cnv.stroke(this.color1)
    cnv.strokeWeight(5)
    cnv.line(
      pos.x + gridSize / 2,
      pos.y,
      pos.x + gridSize / 2,
      pos.y + gridSize
    )
  }
}

class HLine extends SubFood {
  draw() {
    super.draw()
    stroke(this.color1)
    strokeWeight(5)
    line(
      this.x + (gridSize - this.r) / 2,
      this.y + gridSize / 2,
      this.x + gridSize - (gridSize - this.r) / 2,
      this.y + gridSize / 2
    )
  }
  trail(pos, direction) {
    cnv.stroke(this.color1)
    cnv.strokeWeight(5)
    cnv.line(
      pos.x,
      pos.y + gridSize / 2,
      pos.x + gridSize,
      pos.y + gridSize / 2
    )
  }
}

class DRLine extends SubFood {
  draw() {
    super.draw()
    stroke(this.color1)
    strokeWeight(5)
    push()
    translate(this.x + gridSize / 2, this.y + gridSize / 2)
    rotate(-PI / 4)
    line(0, -gridSize / 2, 0, gridSize / 2)
    pop()
  }
  trail(pos, direction) {
    cnv.stroke(this.color1)
    cnv.strokeWeight(5)
    cnv.line(pos.x, pos.y, pos.x + gridSize, pos.y + gridSize)
  }
}

class DLLine extends SubFood {
  draw() {
    super.draw()
    stroke(this.color1)
    strokeWeight(5)
    push()
    translate(this.x + gridSize / 2, this.y + gridSize / 2)
    rotate(PI / 4)
    line(0, -gridSize / 2, 0, gridSize / 2)
    pop()
  }
  trail(pos, direction) {
    cnv.stroke(this.color1)
    cnv.strokeWeight(5)
    cnv.line(pos.x + gridSize, pos.y, pos.x, pos.y + gridSize)
  }
}

class BicolorHFood extends Food {
  draw() {
    noStroke()
    fill(this.color1)
    arc(this.x + gridSize / 2, this.y + gridSize / 2, this.r, this.r, 0, PI)
    fill(this.color2)
    arc(this.x + gridSize / 2, this.y + gridSize / 2, this.r, this.r, PI, TAU)
    super.draw()
  }

  trail(pos, direction) {
    cnv.noStroke()
    cnv.fill(this.color1)
    cnv.rect(pos.x, pos.y, gridSize)
    cnv.fill(this.color2)
    cnv.rect(pos.x, pos.y, gridSize, gridSize / 2)
  }
}
class BicolorVFood extends Food {
  draw() {
    noStroke()
    fill(this.color1)
    arc(
      this.x + gridSize / 2,
      this.y + gridSize / 2,
      this.r,
      this.r,
      PI / 2,
      (3 * PI) / 2
    )
    fill(this.color2)
    arc(
      this.x + gridSize / 2,
      this.y + gridSize / 2,
      this.r,
      this.r,
      (3 * PI) / 2,
      PI / 2
    )
    super.draw()
  }

  trail(pos, direction) {
    cnv.noStroke()
    cnv.fill(this.color1)
    cnv.rect(pos.x, pos.y, gridSize)
    cnv.fill(this.color2)
    cnv.rect(pos.x, pos.y, gridSize / 2, gridSize)
  }
}

class TriangleFood extends Food {
  draw() {
    noStroke()
    fill(this.color1)
    arc(
      this.x + gridSize / 2,
      this.y + gridSize / 2,
      this.r,
      this.r,
      -PI / 4,
      (3 * PI) / 4
    )
    fill(this.color2)
    arc(
      this.x + gridSize / 2,
      this.y + gridSize / 2,
      this.r,
      this.r,
      (3 * PI) / 4,
      -PI / 4
    )
    super.draw()
  }

  trail(pos, direction) {
    cnv.noStroke()
    cnv.fill(this.color1)
    cnv.rect(pos.x, pos.y, gridSize)
    cnv.fill(this.color2)
    cnv.triangle(pos.x, pos.y, pos.x + gridSize, pos.y, pos.x, pos.y + gridSize)
  }
}

class TriangleFood2 extends Food {
  draw() {
    noStroke()
