class SquareFood extends Food {
  draw() {
    push()
    translate(this.x + gridSize / 2, this.y + gridSize / 2)
    noStroke()
    fill(this.color1)
    circle(0, 0, this.r)
    fill(this.color2)
    rectMode(CENTER)
    rotate(PI / 4)
    rect(0, 0, sqrt(2 * (this.r / 2) ** 2))
    pop()
    super.draw()
  }

  trail(pos, direction) {
    cnv.noStroke()
    cnv.fill(this.color1)
    cnv.rect(pos.x, pos.y, gridSize)
    cnv.fill(this.color2)
    cnv.quad(
      pos.x + gridSize / 2,
      pos.y,
      pos.x + gridSize,
      pos.y + gridSize / 2,
      pos.x + gridSize / 2,
      pos.y + gridSize,
      pos.x,
      pos.y + gridSize / 2
    )
  }
}

class Snake {
  constructor(startX = 0, startY = 0) {
    this.respawn(startX, startY)
  }

  respawn(x, y) {
    this.body = [createVector(x, y)]
    this.xSpeed = 1
    this.ySpeed = 0
    this.power = null
    this.subPower = null
  }

  setDirection(x, y) {
    this.xSpeed = x
    this.ySpeed = y
  }

  update() {
    let head = this.body[this.body.length - 1].copy()
    let trail = this.body.shift()
    if (this.power) {
      this.power.trail(trail)
    }
    if (this.subPower) {
      this.subPower.trail(trail)
    }
    head.x += this.xSpeed * gridSize
    head.y += this.ySpeed * gridSize
    this.body.push(head)
  }

  grow() {
    var head = this.body[this.body.length - 1].copy()
    head.x += this.xSpeed * gridSize
    head.y += this.ySpeed * gridSize
    this.body.push(head)
  }

  eat(f) {
    var head = this.body[this.body.length - 1]
    if (head.x === f.x && head.y === f.y) {
      if (f.isPower) {
        this.power = f
        this.grow()
      } else {
        this.subPower = f
      }
      food = food.filter((e) => e !== f)
      return true
    }
    return false
  }

  draw() {
    for (let v of this.body) {
      stroke(WALL_COLOR)
      strokeWeight(5)
      if (this.isInBounds(v)) {
        fill(SNAKE_COLOR)
      } else {
        fill(BG_COLOR)
      }
      rect(v.x, v.y, gridSize, gridSize)
    }
  }

  isInBounds(pos) {
    if (
      pos.x >= width - 2 * gridSize ||
      pos.x < 0 ||
      pos.y >= height - 2 * gridSize ||
      pos.y < 0
    ) {
      return false
    }
    return true
  }

  crashed() {
    var head = this.body[this.body.length - 1]
    // console.log(head.x, head.y, width, height)
    if (!this.isInBounds(head)) {
      return true
    }
    for (let i = 0; i < this.body.length - 1; i++) {
      if (head.x === this.body[i].x && head.y === this.body[i].y) {
        return true
      }
    }
    return false
  }

  die() {
    for (let v of this.body) {
      if (this.power) {
        this.power.trail(v)
      }
    }
  }
}

let texture
function granulate(gA) {
  let gc = createGraphics(cw, cw)
  gc?.loadPixels?.()
  let d = gc.pixelDensity()
  let halfImage = 4 * (cw * d) * (cw * d)
  for (let ii = 0; ii < halfImage; ii += 4) {
    // noprotect
    grainAmount = random(-gA, gA)
    gc.pixels[ii] = gc.pixels[ii] + gA
    gc.pixels[ii + 1] = gc.pixels[ii + 1] + grainAmount
    gc.pixels[ii + 2] = gc.pixels[ii + 2] + grainAmount
    gc.pixels[ii + 3] = gc.pixels[ii + 3] + gA
  }
  gc.updatePixels()
  return gc
}
